CREATE TABLE `gala_results` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `scoresheet_id` int(11) NOT NULL,
  `event_id` int(11) NOT NULL,
  `club_id` int(11) NOT NULL,
  `time_ms` int(11) DEFAULT NULL,
  `is_dq` tinyint(1) DEFAULT 0,
  `dq_reason` varchar(255) DEFAULT NULL,
  `is_verified` tinyint(1) DEFAULT 0,
  `points` int(11) DEFAULT 0,
  `place` int(11) DEFAULT NULL,
  `status` enum('pending','valid','dq','too_fast') DEFAULT 'pending',
  `source_type` enum('live','imported') DEFAULT 'live',
  `source_scoresheet_id` int(11) DEFAULT NULL,
  `imported_by` varchar(100) DEFAULT NULL,
  `imported_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_scoresheet_event_club` (`scoresheet_id`,`event_id`,`club_id`),
  KEY `event_id` (`event_id`),
  KEY `club_id` (`club_id`),
  CONSTRAINT `gala_results_ibfk_1` FOREIGN KEY (`scoresheet_id`) REFERENCES `gala_scoresheets` (`id`) ON DELETE CASCADE,
  CONSTRAINT `gala_results_ibfk_2` FOREIGN KEY (`event_id`) REFERENCES `gala_events` (`id`),
  CONSTRAINT `gala_results_ibfk_3` FOREIGN KEY (`club_id`) REFERENCES `clubs` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3287 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
